// SinlessCSB — GM Hotbar Macro: Roll NPC Initiative (scene-wide)
// Uses the module API (no legacy macro glue, no _initActorUuid handoff)

(async () => {
  const api = game.modules.get("sinlesscsb")?.api;

  if (!api?.rollNpcInitiative) {
    ui.notifications?.error("SinlessCSB: rollNpcInitiative API not found. Is the module active and up to date?");
    return;
  }

  // Optionally pass { sceneId: canvas.scene.id } — API already defaults to active scene
  await api.rollNpcInitiative({});
})();
